KG42.register("rules-97213c80f25dcf434720e59e",{"id":"07-nash_bargaining::v141-c-R002","paper":"07-nash_bargaining","record":{"rule_id":"v141-c-R002","mechanism_id":"v141-a-M01","name":"Social-welfare clearing objective","process_stage":"clearing","market_meaning":"The virtual clearing house coordinates the higher-level updates in the distributed solution of P1's social operating-cost minimization; microgrids solve the lower-level problems. Scope: Step 1 of Algorithm 1, solving P1 for the interconnected-microgrid system. P1's social clearing objective minimizes the sum of microgrid operating costs subject to its specified feasibility constraints. Scope: Problem P1 over all interconnected microgrids in M. The optimal NBP energy trading and scheduling solution also minimizes the total cost of the microgrids in M′. Scope: The microgrids in trading set M′. Condition: The energy trading and scheduling solution is optimal for Problem NBP.","independence_rationale":"Relations governed by the approved function clearing.social_welfare under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["clearing.social_welfare","coordination.local_operator"],"E":[{"edge_id":"v141-c-R002-E001","source":"coordination.local_operator","target":"clearing.social_welfare","type":"links","constraint_ids":["v141-c-R002-C001"],"evidence_ids":["v141-b-g02-E17","v141-b-g02-E35","v141-b-g02-E37"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Problem P1 over all interconnected microgrids in M. | Step 1 of Algorithm 1, solving P1 for the interconnected-microgrid system. | The microgrids in trading set M′.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-E16","v141-b-g02-E17","v141-b-g02-E18","v141-b-g02-E35","v141-b-g02-E37"]},"x":[{"variable_id":"v141-c-R002-x-g_i","symbol":"g_i","meaning":"Wind power supply (local renewable generation usage) of microgrid i over the horizon; listed by the source among the decision variables of Problem P1.","kind":"operational","domain":"{g_i^t, for all t in T}; per-slot values constrained by source constraint (1): 0 \u003c= g_i^t \u003c= eta_i^t G_i; no other domain is stated in the source.","unit":"kW","indices":["i in M","t in T"],"evidence_ids":["v141-b-g02-E18","v141-b-g01-e07"]},{"variable_id":"v141-c-R002-x-q_i","symbol":"q_i","meaning":"Main-grid power schedule of microgrid i, q_i = {q_b,i, q_s,i}: power bought from and sold to the main grid; listed by the source among the decision variables of Problem P1.","kind":"operational","domain":"{q_b,i^t, q_s,i^t, for all t in T}; constrained by (2) 0 \u003c= q_b,i^t \u003c= Q_b,i^max and (3) 0 \u003c= q_s,i^t \u003c= Q_s,i^max.","unit":null,"indices":["i in M","t in T"],"evidence_ids":["v141-b-g02-E18","v141-b-g01-e08","v141-b-g01-e09","v141-b-g01-e21"]},{"variable_id":"v141-c-R002-x-x_n","symbol":"x_n","meaning":"Elastic power-consumption schedule of user n in N_i (demand-response decision); listed by the source among the decision variables of Problem P1.","kind":"operational","domain":"{x_n^t, for all t in T}; constrained by (5) sum_{t in T} x_n^t = D_n and (6) d_n^{t,min} \u003c= x_n^t \u003c= d_n^{t,max}.","unit":null,"indices":["n in N_i","i in M","t in T"],"evidence_ids":["v141-b-g02-E18","v141-b-g01-e10"]},{"variable_id":"v141-c-R002-x-r_c_i","symbol":"r_{c,i}","meaning":"Charging power schedule of the energy storage in microgrid i; listed by the source among the decision variables of Problem P1.","kind":"operational","domain":"{r_{c,i}^t, for all t in T}; constrained by (8) 0 \u003c= r_{c,i}^t \u003c= r_{c,i}^max.","unit":null,"indices":["i in M","t in T"],"evidence_ids":["v141-b-g02-E18","v141-b-g01-e12"]},{"variable_id":"v141-c-R002-x-r_d_i","symbol":"r_{d,i}","meaning":"Discharging power schedule of the energy storage in microgrid i; listed by the source among the decision variables of Problem P1.","kind":"operational","domain":"{r_{d,i}^t, for all t in T}; constrained by (9) 0 \u003c= r_{d,i}^t \u003c= r_{d,i}^max.","unit":null,"indices":["i in M","t in T"],"evidence_ids":["v141-b-g02-E18","v141-b-g01-e12"]},{"variable_id":"v141-c-R002-x-e_i","symbol":"e_i","meaning":"Inter-microgrid energy-trading schedule of microgrid i, e_i = {e_{i,j}^t, for all t in T, for all j in M\\i}; positive entries mean i purchases from j, negative entries mean i sells; listed by the source among the decision variables of Problem P1, and a nonzero e_i places i in M'.","kind":"operational","domain":"Signed real-valued per-slot exchanges {e_{i,j}^t}; the source states no explicit numeric bound, but imposes (15) e_{i,j}^t + e_{j,i}^t = 0 and the traded energy enters the power balance (17).","unit":null,"indices":["i in M","j in M\\i","t in T"],"evidence_ids":["v141-b-g02-E18","v141-b-g01-e19","v141-b-g01-e27"]}],"theta":[{"parameter_id":"v141-c-R002-th-p_b","symbol":"p_b^t","meaning":"Power procurement (buying) price set by the main grid in time slot t; exogenous to the microgrid market and entering C_i(q_i), a component of the operating cost summed in P1's objective.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t in T"],"evidence_ids":["v141-b-g01-e21"]},{"parameter_id":"v141-c-R002-th-p_s","symbol":"p_s^t","meaning":"Power feed-in (selling) price set by the main grid in time slot t; exogenous and subtracted in C_i(q_i), a component of the operating cost summed in P1's objective.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t in T"],"evidence_ids":["v141-b-g01-e21"]},{"parameter_id":"v141-c-R002-th-beta_n","symbol":"beta_n","meaning":"Weight coefficient indicating the sensitivity of user n to deviations of actual consumption from the preferred profile; enters C_n(x_n), a component of the operating cost summed in P1's objective.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["n in N_i"],"evidence_ids":["v141-b-g01-e11"]},{"parameter_id":"v141-c-R002-th-y_n","symbol":"y_n","meaning":"Most preferred power-consumption profile of user n, y_n = {y_n^t, for all t in T}; a given input to C_n(x_n), a component of the operating cost summed in P1's objective.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["n in N_i","t in T"],"evidence_ids":["v141-b-g01-e11"]},{"parameter_id":"v141-c-R002-th-c_s","symbol":"c_s","meaning":"Amortized cost of charging and discharging over the storage lifetime; fixed per-unit coefficient in C_s(r_{c,i}, r_{d,i}), a component of the operating cost summed in P1's objective.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-e16"]}],"phi":[{"constraint_id":"v141-c-R002-C001","kind":"procedural","role":"core","statement":"The virtual clearing house coordinates the higher-level updates in the distributed solution of P1's social operating-cost minimization; microgrids solve the lower-level problems. Scope: Step 1 of Algorithm 1, solving P1 for the interconnected-microgrid system.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","clearing.social_welfare"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E17","v141-b-g02-E35","v141-b-g02-E37"]},{"constraint_id":"v141-c-R002-C002","kind":"mathematical","role":"core","statement":"P1's social clearing objective minimizes the sum of microgrid operating costs subject to its specified feasibility constraints. Scope: Problem P1 over all interconnected microgrids in M.","expression":"min Σ_{i∈M} CO_i(q_i, x_n, r_{c,i}, r_{d,i}) subject to (1)–(3), (5), (6), (8)–(11), (14), (15), and (17); variables: {g_i, q_i, x_n, r_{c,i}, r_{d,i}, e_i, i ∈ M}","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R002-x-g_i","v141-c-R002-x-q_i","v141-c-R002-x-x_n","v141-c-R002-x-r_c_i","v141-c-R002-x-r_d_i","v141-c-R002-x-e_i"],"parameter_refs":[],"evidence_ids":["v141-b-g02-E18","v141-b-g01-e25"]},{"constraint_id":"v141-c-R002-C003","kind":"procedural","role":"core","statement":"The optimal NBP energy trading and scheduling solution also minimizes the total cost of the microgrids in M′. Scope: The microgrids in trading set M′. Condition: The energy trading and scheduling solution is optimal for Problem NBP.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.social_welfare"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E16"]},{"constraint_id":"v141-c-R002-C004","kind":"mathematical","role":"supporting","statement":"Definition of the operating-cost term summed in P1's objective: the operating cost of microgrid i is the sum of its main-grid energy cost, the aggregate discomfort cost of its users, and its energy-storage operation cost. Scope: Definition of the summand of Problem P1 over all interconnected microgrids in M (the source writes the same object as CO_i and, equivalently in notation, C_i^O).","expression":"CO_i(q_i, x_n, r_{c,i}, r_{d,i}) ≜ C_i(q_i) + Σ_{n∈N_i} C_n(x_n) + C_s(r_{c,i}, r_{d,i})","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R002-x-q_i","v141-c-R002-x-x_n","v141-c-R002-x-r_c_i","v141-c-R002-x-r_d_i"],"parameter_refs":[],"evidence_ids":["v141-b-g01-e25","v141-b-g02-E08"]},{"constraint_id":"v141-c-R002-C005","kind":"mathematical","role":"supporting","statement":"Definition of the main-grid energy-cost component of the operating cost summed in P1: microgrid i pays the exogenous buying price for power purchased from the main grid and is credited the feed-in price for power sold, summed over the horizon. Scope: Energy-cost component of the operating cost aggregated in P1 over all interconnected microgrids in M; the buying/selling prices are set by the main grid and are common to all microgrids (source footnote 3).","expression":"C_i(q_i) = Σ_{t∈T} ( p_b^t q_{b,i}^t − p_s^t q_{s,i}^t ), ∀i ∈ M","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R002-x-q_i"],"parameter_refs":["v141-c-R002-th-p_b","v141-c-R002-th-p_s"],"evidence_ids":["v141-b-g01-e21"]},{"constraint_id":"v141-c-R002-C006","kind":"mathematical","role":"supporting","statement":"Definition of the users' discomfort-cost component of the operating cost summed in P1: user n's discomfort is the deviation-sensitivity weight times the sum over the horizon of the squared deviation of actual elastic consumption from the preferred profile. Scope: Discomfort-cost component of the operating cost aggregated in P1 (source states the measure follows the cited discomfort measure [19]).","expression":"C_n(x_n) = β_n Σ_{t∈T} ( x_n^t − y_n^t )^2","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R002-x-x_n"],"parameter_refs":["v141-c-R002-th-beta_n","v141-c-R002-th-y_n"],"evidence_ids":["v141-b-g01-e11","v141-b-g02-E01"]},{"constraint_id":"v141-c-R002-C007","kind":"mathematical","role":"supporting","statement":"Definition of the energy-storage operation-cost component of the operating cost summed in P1: the amortized per-unit charging/discharging cost times the total energy charged plus total energy discharged over the horizon. Scope: Storage-cost component of the operating cost aggregated in P1 (source states the storage cost model follows the cited reference [21]).","expression":"C_s(r_{c,i}, r_{d,i}) = c_s ( Σ_{t∈T} r_{c,i}^t + Σ_{t∈T} r_{d,i}^t )","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R002-x-r_c_i","v141-c-R002-x-r_d_i"],"parameter_refs":["v141-c-R002-th-c_s"],"evidence_ids":["v141-b-g01-e16","v141-b-g02-E05"]}],"pi":[{"evidence_id":"v141-b-g02-E16","location":{"location_id":"src-7e85444402-p06-c1r3__v141-a-M01-clearing","page":6,"printed_page":"2652","section":"IV. PROBLEM ANALYSIS","anchor_text":"respectively. sc We ﬁrst assume that we know the subset M′,5 and focus If on the microgrids in set M","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"Proposition 1: For the microgrids in set M′, the optimal energy trading & scheduling solution to Problem NBP also minimizes the total cost of this group of microgrids i ∈ M′."},{"evidence_id":"v141-b-g02-E17","location":{"location_id":"src-7e85444402-p06-c2r2__v141-a-M01-clearing","page":6,"printed_page":"2652","section":"IV. PROBLEM ANALYSIS","anchor_text":"BP can be decomposed into two sequential subproblems on energy d- trading & scheduling and trading p","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"Theorem 1: The energy-trading bargaining problem NBP can be decomposed into two sequential subproblems on energy trading & scheduling and trading payment, denoted as P1 and P2, respectively. In the first step, we solve a social operating cost minimization problem P1 for the interconnected-microgrids system, which yields the optimal energy scheduling and energy trading for all microgrids. Those microgrids that trade energy with other microgrids form the set M′. In the second step, microgrids in set M′ bargain with each other to determine the energy-trading payments in P2."},{"evidence_id":"v141-b-g02-E18","location":{"location_id":"src-7e85444402-p06-c2r2__v141-a-M01-clearing","page":6,"printed_page":"2652","section":"IV. PROBLEM ANALYSIS","anchor_text":"BP can be decomposed into two sequential subproblems on energy d- trading & scheduling and trading p","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"P1: Social operating cost minimization problem:\nmin ∑_{i∈M} CO_i(q_i, x_n, r_{c,i}, r_{d,i})\nsubject to (1)–(3), (5), (6), (8)–(11), (14), (15), and (17),\nvariables: { g_i, q_i, x_n, r_{c,i}, r_{d,i}, e_i, i ∈ M }.\nSolving P1 determines the optimal energy trading & scheduling {g_i^*, q_i^*, x_n^*, r_{c,i}^*, r_{d,i}^*, e_i^*} for each microgrid i ∈ M. If a microgrid i has a nonzero energy trading vector e_i, then it belongs to set M′, and will participate in the payment bargaining in Problem P2. For the non-trading microgrids j ∈ M\\M′, they do not participate in the payment bargaining and their operating costs are the same as the disagreement points C_j^{Non}."},{"evidence_id":"v141-b-g02-E35","location":{"location_id":"src-7e85444402-p08-c2r1__v141-a-M01-activation","page":8,"printed_page":"2654","section":"V.C Algorithm Design and Implementation","anchor_text":"IEEE TRANSACTIONS ON SMART GRID, VOL. 9, NO. 4, JULY 2018 Algorithm 1 Distributed Algorithm Solving ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"Algorithm 1 Distributed Algorithm Solving P1 and P2\n1: Step 1: solve Problem P1.\n2: Initialization: iteration index k = 1, error tolerance ϵ1 > 0, stepsize ρ1(0) = 1, and initial multipliers λ(0) = 0.\n3: repeat\n4: At k-th iteration,\n5: Lower Level Problem: Microgrid i solves Problem P1-MGi based on the current value of dual variables λ(k);\n6: Higher Level Problem: The virtual clearing house makes update according to (21) and (22).\n7: Update iteration index k = k + 1;\n8: until terminal condition is satisfied ...\n9: Step 2: solve Problem P2.\n10: Initialization: iteration index k = 1, error tolerance ϵ2 > 0, stepsize ρ2(0) = 1, and initial multipliers γ(0) = 0.\n11: repeat\n12: At k-th iteration,\n13: Lower Level Problem: Microgrid i solves Problem P2-MGi based on the current value of dual variables γ(k);\n14: Higher Level Problem: The virtual clearing house makes updates according to the rules in (25) and (26).\n15: Update iteration index k = k + 1;\n16: until terminal condition is satisfied ...\n17: end"},{"evidence_id":"v141-b-g02-E37","location":{"location_id":"src-7e85444402-p08-c2r4__v141-a-M01-activation","page":8,"printed_page":"2654","section":"V.C Algorithm Design and Implementation","anchor_text":"To implement the solution method for solving the energy trading and payment problems P1 and P2, we d","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"We introduce the concept of virtual clearing house for solving the higher level problem. The virtual clearing house is a communication and computing module, which provides clearing service of energy trading and payment for all the microgrids. At the beginning of each daily operation, the virtual clearing house updates the auxiliary and dual variables according to (21), (22) and (25), (26), and broadcasts to all participating microgrids when solving P1 and P2, respectively. All the participating microgrids concurrently solve P1-MGi and P2-MGi and report their energy trading schedules and payments to the virtual clearing house."},{"evidence_id":"v141-b-g01-e07","location":{"location_id":"src-7e85444402-p03-c1r4__v141-a-M01-clearing","page":3,"printed_page":null,"section":"III.A Power Scheduling in Each Microgrid","anchor_text":"p g i i g p co kW capacity. We assume that microgrid i has installed wind ov turbine generators with","equation_id":"(1)","figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"We assume that microgrid i has installed wind turbine generators with total generation capacity G_i (kW), and have the following constraint for the wind power supply g_i = {g_i^t, ∀t ∈ T}: 0 ≤ g_i^t ≤ η_i^t G_i, ∀t ∈ T, ∀i ∈ M, (1) where η_i^t G_i denotes the maximum available wind power of microgrid i in time slot t. Note that the local wind power usage g_i^t of microgrid i in time slot t can be less but no greater than the available wind power η_i^t G_i, because the microgrid operator can either curtail excess wind power generation or sell excess generation back to the main grid."},{"evidence_id":"v141-b-g01-e08","location":{"location_id":"src-7e85444402-p03-c2r1__v141-a-M01-clearing","page":3,"printed_page":null,"section":"III.A Power Scheduling in Each Microgrid","anchor_text":"NECTED MICROGRIDS 2649 Different from conventional power generations, wind power generation does not","equation_id":"(2)","figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"When the local wind power generation is not adequate to meet the demand, microgrid i can also purchase power from the main power grid. Let q_{b,i}^t denote the power bought from the main grid by microgrid i in time slot t, and define q_{b,i} = {q_{b,i}^t, ∀t ∈ T}. The purchased power q_{b,i} is subject to the following constraint: 0 ≤ q_{b,i}^t ≤ Q_{b,i}^{max}, ∀t ∈ T, ∀i ∈ M, (2) where Q_{b,i}^{max} denotes the maximum amount of power that microgrid i can purchase from the main grid, due to physical capacity limit."},{"evidence_id":"v141-b-g01-e09","location":{"location_id":"src-7e85444402-p03-c2r2__v141-a-M01-clearing","page":3,"printed_page":null,"section":"III.A Power Scheduling in Each Microgrid","anchor_text":"0 ≤qb,i ≤Qb,i , ∀t ∈T , ∀i ∈M, (2) where Qmaxb,i denotes the maximum amount of power that microgrid ","equation_id":"(3)","figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"When the microgrid has excess local wind power generation, it can sell power back to the main grid under a feed-in tariff contract [18]. Let q_{s,i}^t denote the power sold to the main grid by microgrid i in time slot t, and define q_{s,i} = {q_{s,i}^t, ∀t ∈ T}. The power sold to the main grid q_{s,i} satisfies the following constraint: 0 ≤ q_{s,i}^t ≤ Q_{s,i}^{max}, ∀t ∈ T, ∀i ∈ M, (3) where Q_{s,i}^{max} denotes the maximum allowed amount of power that microgrid i can sell to the main grid."},{"evidence_id":"v141-b-g01-e10","location":{"location_id":"src-7e85444402-p03-c2r4__v141-a-M01-clearing","page":3,"printed_page":null,"section":"III.A Power Scheduling in Each Microgrid","anchor_text":"conditioning) and washer demands, can be ﬂexibly scheduled nd over time. For user n ∈Ni in microgrid","equation_id":"(5)","figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"condition"},"source_text":"The demand response program can only control the elastic loads, and should be subject to the following constraints: Σ_{t∈T} x_n^t = D_n, ∀n ∈ N_i, ∀i ∈ M, (5) d_n^{t,min} ≤ x_n^t ≤ d_n^{t,max}, ∀t ∈ T, ∀n ∈ N_i, ∀i ∈ M, (6) where constraint (5) corresponds to the prescribed total energy requirement D_n in the entire operation horizon. Constraint (6) provides a lower bound d_n^{t,min} and upper bound d_n^{t,max} for the power consumption of user n in each time slot t."},{"evidence_id":"v141-b-g01-e11","location":{"location_id":"src-7e85444402-p04-c1r1__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III.A Power Scheduling in Each Microgrid","anchor_text":"2650 provides a lower bound dt,minn and upper bound dt,maxn for the en power consumption of user n i","equation_id":"(7)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Let y_n = {y_n^t, ∀t ∈ T} denote the most preferred power consumption of user n. When the actual power consumption x_n deviates from the preferred power consumption y_n, user n will experience discomfort. Similar as the discomfort measure in [19], we define the discomfort cost of user n as C_n(x_n) = β_n Σ_{t∈T} (x_n^t − y_n^t)^2, (7) where (x_n^t − y_n^t)^2 measures how much the actual power consumption differs from the preferred power consumption. Weighted coefficient β_n is used to indicate the sensitivity of user n towards the power consumption deviation."},{"evidence_id":"v141-b-g01-e12","location":{"location_id":"src-7e85444402-p04-c1r2__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III.A Power Scheduling in Each Microgrid","anchor_text":"user n as de Cn(xn) = βn xtn −ytn 2, (7) ho t∈T B. where (xtn −ytn)2 measures how much the actual po","equation_id":"(8)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"First, the charging and discharging power in each time slot t are bounded, and satisfy the following constraints: 0 ≤ r_{c,i}^t ≤ r_{c,i}^{max}, ∀t ∈ T, ∀i ∈ M, (8) 0 ≤ r_{d,i}^t ≤ r_{d,i}^{max}, ∀t ∈ T, ∀i ∈ M, (9) where r_{c,i}^{max} and r_{d,i}^{max} denote the maximum charging and discharging rates of energy storage in microgrid i, respectively."},{"evidence_id":"v141-b-g01-e16","location":{"location_id":"src-7e85444402-p04-c2r1__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III.A Power Scheduling in Each Microgrid","anchor_text":"IEEE TRANSACTIONS ON SMART GRID, VOL. 9, NO. 4, JULY 2018 he energy level sTi to be the same as its ","equation_id":"(12)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Last, to incorporate the degradation of energy storage caused by charging and discharging, we introduce c_s as the amortized cost of charging and discharging over the lifetime, and model the cost of energy storage operation [21] as C_s(r_{c,i}, r_{d,i}) = c_s ( Σ_{t∈T} r_{c,i}^t + Σ_{t∈T} r_{d,i}^t ), (12) where r_{c,i} = {r_{c,i}^t, ∀t ∈ T} and r_{d,i} = {r_{d,i}^t, ∀t ∈ T} denote the charging and discharging amount over the operation horizon T in microgrid i, respectively."},{"evidence_id":"v141-b-g01-e19","location":{"location_id":"src-7e85444402-p05-c2r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"III.C Energy Trading Among Microgrids","anchor_text":"NECTED MICROGRIDS 2651 ue The energy trading and payment among microgrids should di- satisfy the mar","equation_id":"(15)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"The energy trading and payment among microgrids should satisfy the market clearing constraints: e_{i,j}^t + e_{j,i}^t = 0, ∀t ∈ T, ∀j ∈ M\\i, ∀i ∈ M, (15)"},{"evidence_id":"v141-b-g01-e21","location":{"location_id":"src-7e85444402-p03-c2r3__v141-a-M01-pricing","page":3,"printed_page":null,"section":"III.A Power Scheduling in Each Microgrid","anchor_text":"ch (buying) price and denote pts as the power feed-in (selling) price3 set by the main grid in time ","equation_id":"(4)","figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"We denote p_b^t as the power procurement (buying) price and denote p_s^t as the power feed-in (selling) price set by the main grid in time slot t. For notational simplicity, we let q_i = {q_{b,i}, q_{s,i}} denote the main grid power schedule of microgrid i over T time slots. The energy cost of microgrid i is written as C_i(q_i) = Σ_{t∈T} ( p_b^t q_{b,i}^t − p_s^t q_{s,i}^t ), ∀i ∈ M. (4) 3We assume that all the microgrids are connected to the same main grid, and the power buying/selling prices for all the microgrids are the same."},{"evidence_id":"v141-b-g01-e25","location":{"location_id":"src-7e85444402-p04-c2r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III.B Single Microgrid's Cost Minimization Problem","anchor_text":"ge denote the operating cost of microgrid i asng is COi qi, xn, rc,i, rd,i ≜Ci qi + Cn(xn) + Cs rc,i","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"For simplicity, we denote the operating cost of microgrid i as C_i^O(q_i, x_n, r_{c,i}, r_{d,i}) ≜ C_i(q_i) + Σ_{n∈N_i} C_n(x_n) + C_s(r_{c,i}, r_{d,i}). Therefore, we formulate the microgrid operator's operating cost minimization problem as follows. Cost minimization problem for Microgrid i (P-MG_i): min C_i^O(q_i, x_n, r_{c,i}, r_{d,i}) subject to (1)–(3), (5), (6), (8)–(11), (13), and (14) variables: g_i, q_i, x_n, r_{c,i}, r_{d,i}."},{"evidence_id":"v141-b-g01-e27","location":{"location_id":"src-7e85444402-p05-c1r4__v141-a-M01-pricing","page":5,"printed_page":null,"section":"III.C Energy Trading Among Microgrids","anchor_text":"We consider that each microgrid i ∈M bargains with all the other interconnected microgrids to determ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"We consider that each microgrid i ∈ M bargains with all the other interconnected microgrids to determine the amount of energy trading e_i = {e_{i,j}^t, ∀t ∈ T, ∀j ∈ M\\i} and the associated payment π_i = {π_{i,j}, ∀j ∈ M\\i}. Here e_{i,j}^t denotes the amount of energy that microgrid i exchanges with microgrid j in time slot t, and π_{i,j} denotes the associated payment for energy trading between microgrid i and microgrid j. If microgrid i purchases energy from microgrid j in time slot t, then e_{i,j}^t > 0; otherwise, microgrid i sells energy to microgrid j and e_{i,j}^t \u003c 0. Similarly, if microgrid i makes payment to microgrid j, then π_{i,j} > 0; otherwise microgrid i receives payment from microgrid j and π_{i,j} \u003c 0. 4Note that the payments π_i are determined through bargaining between microgrids, and are not necessary linear in terms of the energy exchange e_i."},{"evidence_id":"v141-b-g02-E01","location":{"location_id":"src-7e85444402-p04-c1r1__v141-a-M01-clearing","page":4,"printed_page":"2650","section":"III.A Power Scheduling in Each Microgrid","anchor_text":"2650 provides a lower bound dt,minn and upper bound dt,maxn for the en power consumption of user n i","equation_id":"(7)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Cn(xn) = βn ∑_{t∈T} (x_n^t − y_n^t)^2,   (7)   where (x_n^t − y_n^t)^2 measures how much the actual power consumption differs from the preferred power consumption. Weighted coefficient βn is used to indicate the sensitivity of user n towards the power consumption deviation."},{"evidence_id":"v141-b-g02-E05","location":{"location_id":"src-7e85444402-p04-c2r1__v141-a-M01-clearing","page":4,"printed_page":"2650","section":"III.A Power Scheduling in Each Microgrid","anchor_text":"IEEE TRANSACTIONS ON SMART GRID, VOL. 9, NO. 4, JULY 2018 he energy level sTi to be the same as its ","equation_id":"(12)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Cs(r_{c,i}, r_{d,i}) = c_s ( ∑_{t∈T} r_{c,i}^t + ∑_{t∈T} r_{d,i}^t ),   (12)   where r_{c,i} = {r_{c,i}^t, ∀t ∈ T } and r_{d,i} = {r_{d,i}^t, ∀t ∈ T } denote the charging and discharging amount over the operation horizon T in microgrid i, respectively."},{"evidence_id":"v141-b-g02-E08","location":{"location_id":"src-7e85444402-p04-c2r4__v141-a-M01-clearing","page":4,"printed_page":"2650","section":"III.B Single Microgrid's Cost Minimization Problem","anchor_text":"ge denote the operating cost of microgrid i asng is COi qi, xn, rc,i, rd,i ≜Ci qi + Cn(xn) + Cs rc,i","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"CO_i(q_i, x_n, r_{c,i}, r_{d,i}) ≜ C_i(q_i) + ∑_{n∈N_i} C_n(x_n) + C_s(r_{c,i}, r_{d,i}).\nCost minimization problem for Microgrid i (P-MGi):\nmin CO_i(q_i, x_n, r_{c,i}, r_{d,i})\nsubject to (1)–(3), (5), (6), (8)–(11), (13), and (14)\nvariables: g_i, q_i, x_n, r_{c,i}, r_{d,i}.\nWe can verify that Problem P-MGi is convex, and can be efficiently solved by several standard optimization techniques [22]."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-activation","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-pricing"],"extras":{"decision_anchor":"clearing.social_welfare","graph_fact_supports":[[{"evidence_id":"v141-b-g02-E35","quote":"1: Step 1: solve Problem P1. 2: Initialization: iteration index k = 1, error tolerance ϵ1 > 0, stepsize ρ1(0) = 1, and initial multipliers λ(0) = 0. 3: repeat 4: At k-th iteration, 5: Lower Level Problem: Microgrid i solves Problem P1-MGi based on the current value of dual variables λ(k); 6: Higher Level Problem: The virtual clearing house makes update according to (21) and (22)."},{"evidence_id":"v141-b-g02-E17","quote":"In the first step, we solve a social operating cost minimization problem P1 for the interconnected-microgrids system, which yields the optimal energy scheduling and energy trading for all microgrids."},{"evidence_id":"v141-b-g02-E37","quote":"The virtual clearing house is a communication and computing module, which provides clearing service of energy trading and payment for all the microgrids."}],[{"evidence_id":"v141-b-g02-E18","quote":"P1: Social operating cost minimization problem: min ∑_{i∈M} CO_i(q_i, x_n, r_{c,i}, r_{d,i}) subject to (1)–(3), (5), (6), (8)–(11), (14), (15), and (17),"}],[{"evidence_id":"v141-b-g02-E16","quote":"Proposition 1: For the microgrids in set M′, the optimal energy trading & scheduling solution to Problem NBP also minimizes the total cost of this group of microgrids i ∈ M′."}]],"C2_formalization":{"graph_sha256":"e398fcb0524229526c68bf9aa1ca0f155bdffa0410435dc435c8d95de0637b95","applicability":"formalized","reason":"Applicability=formalized because evidence v141-b-g02-E18 states P1's social operating cost minimization problem explicitly (objective, referenced constraint set, and the P1 decision-variable list), and this frozen rule contains the node clearing.social_welfare. C.2 transcribes that objective on v141-c-R002-C002 (expression added, formalization_origin set to source; constraint_id, statement, role, members and the original evidence id kept, with one same-mechanism support id appended). C.1 left x and theta empty with the caveat that typed objects were outside the graph draft and that this 'does not assert that the source lacks variables'; C.2 therefore populates x with the six P1 decision vectors (g_i, q_i, x_n, r_{c,i}, r_{d,i}, e_i) and theta with the five fixed cost-side inputs of the objective (p_b^t, p_s^t, beta_n, y_n, c_s), each bound to clearing.social_welfare and each carrying same-mechanism source evidence. C.2 deliberately does NOT restate the constants of P1's referenced feasibility constraints (1)-(3), (5), (6), (8)-(11), (14), (15), (17): those constraints and their symbols belong to the rules/evidence that own them, and the source itself only references them by number, so no cross-rule facts are imported. v141-c-R002-C001 remains an unformalized procedure (Algorithm 1 higher/lower-level iteration coordinated by the virtual clearing house, edge v141-c-R002-E001), and v141-c-R002-C003 remains unformalized: it is a proposition-level claim whose expression would require NBP/argmin symbols and payment variables (pi_i, C_i^{Non}) that are outside this rule's declared objects, so no formula is invented for it. B evidence is UNREVIEWED in this experiment (audit_performed=false, scientific_acceptance=false); all cited ids are same-mechanism candidate support and no independent source audit or downstream verification is claimed.","bindings":[{"object_id":"v141-c-R002-x-g_i","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"g_i is listed by the source among P1's decision variables (evidence v141-b-g02-E18). It is bound to the frozen node clearing.social_welfare because that node carries this rule's social operating-cost objective, which is optimized over the decision vectors of every interconnected microgrid i in M; no edge of this rule constrains g_i individually (the energy-allocation and balance relations live in other rules)."},{"object_id":"v141-c-R002-x-q_i","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"q_i (main-grid purchase/sale schedule) is one of P1's decision vectors in evidence v141-b-g02-E18 and is an argument of the operating cost CO_i aggregated by the objective at node clearing.social_welfare. It is not connected to this rule's single edge, which encodes the higher-level clearing procedure (C001), not the main-grid schedule."},{"object_id":"v141-c-R002-x-x_n","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"x_n (elastic consumption schedule) is one of P1's decision vectors in evidence v141-b-g02-E18 and an argument of CO_i, the summand of the objective at node clearing.social_welfare; it is also the argument of P1's discomfort-cost component (C006)."},{"object_id":"v141-c-R002-x-r_c_i","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"r_{c,i} (storage charging schedule) is one of P1's decision vectors in evidence v141-b-g02-E18 and an argument of CO_i, the summand of the objective at node clearing.social_welfare; it also determines the storage-cost component of that objective (C007)."},{"object_id":"v141-c-R002-x-r_d_i","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"r_{d,i} (storage discharging schedule) is one of P1's decision vectors in evidence v141-b-g02-E18 and an argument of CO_i, the summand of the objective at node clearing.social_welfare; it also determines the storage-cost component of that objective (C007)."},{"object_id":"v141-c-R002-x-e_i","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"e_i is listed by the source among P1's decision variables (evidence v141-b-g02-E18); it is bound to node clearing.social_welfare because P1's social objective covers all microgrids in M and its optimal trading vector decides the scope of the subsequent payment stage (nonzero e_i places i in M'). The pairwise antisymmetry relation on e_i is owned by the clearing/inter-area rule and is only referenced here by equation number (15)."},{"object_id":"v141-c-R002-th-p_b","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"p_b^t is an exogenous fixed input (main-grid buying price, evidence v141-b-g01-e21) entering C_i(q_i), a component of CO_i, the summand of the objective at node clearing.social_welfare (transcribed in C002 and C005). No edge applies: the price is set by the main grid, not by the coordination relation encoded in v141-c-R002-E001."},{"object_id":"v141-c-R002-th-p_s","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"p_s^t is an exogenous fixed input (feed-in selling price, evidence v141-b-g01-e21) subtracted in C_i(q_i), a component of CO_i, the summand of P1's objective at node clearing.social_welfare (transcribed in C002 and C005). No edge applies for the same reason as for p_b^t."},{"object_id":"v141-c-R002-th-beta_n","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"beta_n is a fixed sensitivity weight (evidence v141-b-g01-e11) entering C_n(x_n), the discomfort-cost component of CO_i aggregated by the objective at node clearing.social_welfare (transcribed in C002 and C006)."},{"object_id":"v141-c-R002-th-y_n","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"y_n is the given preferred consumption profile of user n (evidence v141-b-g01-e11) that fixes the reference point of C_n(x_n), the discomfort-cost component of CO_i aggregated by the objective at node clearing.social_welfare (transcribed in C006)."},{"object_id":"v141-c-R002-th-c_s","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"c_s is the fixed amortized charging/discharging cost coefficient (evidence v141-b-g01-e16) entering C_s(r_{c,i}, r_{d,i}), the storage-cost component of CO_i aggregated by the objective at node clearing.social_welfare (transcribed in C007)."},{"object_id":"v141-c-R002-C002","node_ids":["clearing.social_welfare","coordination.local_operator"],"edge_ids":["v141-c-R002-E001"],"rationale":"C002 is the formalized P1 objective; its value function is a property of node clearing.social_welfare (the social operating-cost minimization), and P1 is solved in Step 1 of Algorithm 1 through the higher-level updates performed by the virtual clearing house, which is exactly the relation encoded by edge v141-c-R002-E001 linking coordination.local_operator to clearing.social_welfare. The decision-variable list in the expression is bound to the six x objects declared in this rule."},{"object_id":"v141-c-R002-C004","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"C004 defines CO_i, the summand of the objective at node clearing.social_welfare, so it binds to that node only; it is a definition of a cost function and not part of the coordination procedure encoded by this rule's edge."},{"object_id":"v141-c-R002-C005","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"C005 defines the energy-cost component C_i(q_i) of CO_i, the summand of the objective at node clearing.social_welfare; the first argument of the component is bound to this rule's declared q_i object."},{"object_id":"v141-c-R002-C006","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"C006 defines the discomfort-cost component C_n(x_n) of CO_i, the summand of the objective at node clearing.social_welfare; it is bound to this rule's declared x_n object and to the fixed inputs beta_n and y_n."},{"object_id":"v141-c-R002-C007","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"C007 defines the storage-cost component C_s(r_{c,i}, r_{d,i}) of CO_i, the summand of the objective at node clearing.social_welfare; it is bound to this rule's declared r_{c,i} and r_{d,i} objects and to the fixed input c_s."}],"revision_requests":["Non-blocking request to C.1: P1's feasibility set is present in this rule only as the source's equation-number list ((1)–(3), (5), (6), (8)–(11), (14), (15), (17)) with no constraint objects reachable from clearing.social_welfare; if cross-rule linkage of P1's feasibility constraints is required for the formalization, C.1 should add the corresponding constraint-bearing nodes/edges rather than have C.2 import constraint facts from other rules."]}},"quarantined_references":[]}});
